const nameEl=document.getElementById('name');
const catEl=document.getElementById('cat');
const whenEl=document.getElementById('when');
const msg=document.getElementById('msg');
const listEl=document.getElementById('list');
const emptyEl=document.getElementById('empty');
const filterEl=document.getElementById('filter');
let chores=[];
let revs={};
function norm(s){return String(s||'').trim().replace(/\s+/g,' ');}
function say(t,isErr){msg.textContent=t;msg.className=isErr?'err':'';}
function render(){
  const keep=filterEl.value;
  const seen=[];
  for(const c of chores){const k=norm(c.category);if(k&&!seen.includes(k))seen.push(k);}
  filterEl.textContent='';
  const all=document.createElement('option');all.value='';all.textContent='Everyone';filterEl.appendChild(all);
  for(const k of seen){const o=document.createElement('option');o.value=k;o.textContent=k;filterEl.appendChild(o);}
  filterEl.value=seen.includes(keep)?keep:'';
  const f=filterEl.value;
  listEl.textContent='';
  let shown=0;
  for(const c of chores){
    if(f&&norm(c.category)!==f)continue;
    shown++;
    const li=document.createElement('li');
    li.setAttribute('data-hook','item');
    if(c.done)li.className='done';
    const chk=document.createElement('label');chk.className='check';
    const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!c.done;
    const main=document.createElement('span');main.className='main';
    const nm=document.createElement('span');nm.className='cname';nm.textContent=c.name;
    main.appendChild(nm);
    if(c.when){const w=document.createElement('span');w.className='meta';w.textContent=' · '+c.when;main.appendChild(w);}
    chk.appendChild(cb);chk.appendChild(main);
    cb.addEventListener('change',()=>toggle(c.id,cb.checked));
    const tag=document.createElement('span');tag.className='tag';tag.setAttribute('data-hook','category');tag.textContent=c.category;
    const rm=document.createElement('button');rm.type='button';rm.className='secondary';rm.setAttribute('data-hook','item-remove');rm.textContent='Remove';
    rm.setAttribute('aria-label','Remove '+c.name);
    rm.addEventListener('click',()=>remove(c.id,c.name));
    li.appendChild(chk);li.appendChild(tag);li.appendChild(rm);
    listEl.appendChild(li);
  }
  emptyEl.hidden=shown>0;
}
async function load(){
  const r=await tessera.call('data.read',{});
  chores=Array.isArray(r.data.chores)?r.data.chores:[];
  revs=(r.revisions&&r.revisions.chores)||{};
  render();
}
async function add(){
  const name=norm(nameEl.value),cat=norm(catEl.value);
  if(!name||!cat){say('Please type the chore and who does it.',true);return;}
  const rec={name:name,category:cat,when:norm(whenEl.value),done:false};
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'chores',record:rec}]});
    nameEl.value='';whenEl.value='';
    await load();
    say('Added "'+name+'" for '+cat+'.');
    nameEl.focus();
  }catch(e){say('Could not add the chore. Nothing was changed. Please try again.',true);}
}
async function toggle(id,val){
  try{
    await tessera.call('data.patch',{operations:[{op:'replace',collection:'chores',id:id,revisionCount:revs[id],fields:{done:val}}]});
    await load();
  }catch(e){say('Could not update the chore. Please try again.',true);await load();}
}
async function remove(id,name){
  try{
    await tessera.call('data.patch',{operations:[{op:'remove',collection:'chores',id:id,revisionCount:revs[id]}]});
    await load();
    say('Removed "'+name+'".');
  }catch(e){say('Could not remove the chore. Please try again.',true);}
}
document.getElementById('add').addEventListener('click',add);
for(const el of [nameEl,catEl,whenEl]){el.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();add();}});}
filterEl.addEventListener('change',render);
load().catch(()=>say('Could not load the chores.',true));
